select
,null orgData ,null datauuid from MST_EXCHARGE_QUOTE
#{exchargeCode,jdbcType=VARCHAR}
and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') >= #{tradeDateBegin}
and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') <= #{tradeDateEnd}
and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') = #{tradeDate}
and DATASOURCE_TYPE = #{datasourceType}
and STATUS = #{status}
union all select EXCHARGE_CODE as exchargeCode, DATASOURCE_TYPE as datasourceType, TRADE_DATE as tradeDate, null as openPrice, null as closePrice, null as midPrice, null as highPrice, null as lowPrice, null as basisCyy, null as quotUnit, STATUS as statusValid, ERR_MSG as errMsg, null as inputType, CREATE_USER as createUser, CREATE_DEPT as createDept, CREATE_TIME as createTime, UPDATE_USER as updateUser, UPDATE_TIME as updateTime, ORG_DATA as orgData, DATAUUID as datauuid from MST_EXCHARGE_QUOTE_ERRODATA
#{exchargeCode,jdbcType=VARCHAR}
and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') >= #{tradeDateBegin}
and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') <= #{tradeDateEnd}
and STR_TO_DATE(TRADE_DATE,'%Y-%m-%d') = #{tradeDate}
and DATASOURCE_TYPE = #{datasourceType}
and STATUS = #{status}
order by tradeDate desc,exchargeCode asc

